  let refill=0; for(let i=1;i<=order.length && cost(order.slice(0,i))<=7424;i++)refill=i;
  return {analysis,packed,prep,visible,capacity:{n,visible:visible.length,allQuestionTexts:all.length,refillBudgetAlone:refill,refillWithSelectionLimit:Math.min(refill,analysis.context.scope.selectionLimits.questions),bInputByteEstimate:cost(visible)}};
}
