      if(input.method==='GET'){const s=await fetch(url+input.path,{headers:input.headers,signal:input.signal});return {status:s.status,body:await s.text()};}
      const b=frozen[n+'-'+arm];
      rec.wireSha256=hash(JSON.stringify(b)); save('request-'+n+'-'+arm+'.json',b);
      const start=performance.now();rec.rawContent=''; const http=await fetch(url+input.path,{method:'POST',headers:input.headers,body:JSON.stringify(b),signal:input.signal});rec.http=http.status;
      if(!http.ok){rec.transportError=await http.text();return {status:http.status,body:rec.transportError};}
      let buf='';const decoder=new TextDecoder();
      for await(const chunk of http.body!){buf+=decoder.decode(chunk,{stream:true});let at;
        while((at=buf.indexOf('\n'))>=0){const ln=buf.slice(0,at).trim();buf=buf.slice(at+1);if(!ln.startsWith('data:')||ln.includes('[DONE]'))continue;
          const e=JSON.parse(ln.slice(5));if(e.usage)rec.usage=e.usage;if(e.timings)rec.timings=e.timings;
          const ch=e.choices?.[0];if(ch?.finish_reason)rec.finish=ch.finish_reason;if(ch?.delta?.content){rec.ttftMs??=performance.now()-start;rec.rawContent+=ch.delta.content;}
        }
      }
      rec.requestMs=performance.now()-start;
      return {status:http.status,body:JSON.stringify({model:b.model,choices:[{message:{content:rec.rawContent},finish_reason:rec.finish}],usage:rec.usage,timings:rec.timings})};
    }});
